mapper.select:
select
f.file_relation_id as fileRelationId, sec.Sec_Name as secName, c1.C_Name as dfUnitName, c1.C_Abbreviation as dfUnitAbbName, con.Con_Name as conName, con.Con_Code as conCode, mn.* from Design_Feasibility mn
left join Sys_File f on f.FileID=mn.Df_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sys_Company c1 on c1.C_Id=mn.Df_Unit
${params.authSql}
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Df_Create_Time desc
